(25791, 'Mark 16:8', 'Mark', 16, 8, 'هغوی د قبر څخه راووتلې او وتښتېدلې، ځکه چې د ډېرې وېرې لړزېدلې او وارخطا شوې وې. هغوی هېچا ته څه ونه ویل، ځکه چې وېرېدلې وې. عیسی مریم مجدلیې ته ښکاره کیږي (متي ۲۸‏:‌۹‌‏-‌۱۰ او یوحنا ۲۰‏:‌۱۱‌‏-‌۱۸) [', 'هغوی د قبر چخه راووتلې او وتشتېدلې، جکه چې د دېرې وېرې لرزېدلې او وارخطا شوې وې. هغوی هېچا ته چه ونه ویل، جکه چې وېرېدلې وې. عیسی مریم مجدلیې ته شکاره کیزی (متی ۲۸‏:‌۹‌‏-‌۱۰ او یوحنا ۲۰‏:‌۱۱‌‏-‌۱۸) [', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25792, 'Mark 16:9', 'Mark', 16, 9, 'کله چې عیسی د یکشنبې په ورځ سهار وختي د مړو نه راژوندی شو، نو لومړی مریم مجدلیې ته چې هغه ورڅخه اووه پېریان ویستلي وو ښکاره شو.', 'کله چې عیسی د یکشنبې په ورج سهار وختی د مرو نه راژوندی شو، نو لومری مریم مجدلیې ته چې هغه ورچخه اووه پېریان ویستلی وو شکاره شو.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25793, 'Mark 16:10', 'Mark', 16, 10, 'هغه لاړه او څه چې پېښ شوي وو هغه یې د عیسی نژدې ملګرو ته چې ویر او ژړاګانې یې کولې، وویل.', 'هغه لاره او چه چې پېش شوی وو هغه یې د عیسی نژدې ملګرو ته چې ویر او ژراګانې یې کولې، وویل.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25794, 'Mark 16:11', 'Mark', 16, 11, 'کله چې هغوی واورېدل چې عیسی ژوندی شوی دی او مریم لیدلی دی، نو باور یې ورباندې ونه کړ. عیسی دوو شاګردانو ته ښکاره کیږي (لوقا ۲۴‏:‌۱۳‌‏-‌۳۵)', 'کله چې هغوی واورېدل چې عیسی ژوندی شوی دی او مریم لیدلی دی، نو باور یې ورباندې ونه کر. عیسی دوو شاګردانو ته شکاره کیزی (لوقا ۲۴‏:‌۱۳‌‏-‌۳۵)', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
(25795, 'Mark 16:12', 'Mark', 16, 12, 'له هغې وروسته عیسی په بله څېره کې خپلو دوو شاګردانو ته چې د اورشلیم څخه کلي ته روان وو، ښکاره شو.', 'له هغې وروسته عیسی په بله چېره کې خپلو دوو شاګردانو ته چې د اورشلیم چخه کلی ته روان وو، شکاره شو.', 'NT', 'afghan2023', 'afghan', '', '', 1761237833, 1761237833),
